"""C1 coarticulation prior (sang/coartic.py). CPU only, synthetic clips built from a known prior."""
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from sang import coartic as co

TOKENS = ["p", "a", "i", "u", "t", "f"]


def make_clip(rng, n=200, lag=2, noise=0.1):
    """Real lips generated by a Cohen-Massaro process with known targets and dominance."""
    spikes, f = [], 3
    while f < n - 3:
        spikes.append((f, TOKENS[rng.integers(len(TOKENS))]))
        f += int(rng.integers(2, 6))
    pause = np.zeros(n, bool)
    ev = co.events(spikes, pause)
    true = {"p": -1.5, "a": 1.5, "i": 0.3, "u": -0.2, "t": 0.0, "f": -0.8}
    alpha = {k: 1.0 for k in co.CLASSES}
    theta = {k: 0.5 for k in co.CLASSES}
    lip = co.prior_trace(ev, n, true, alpha, theta, lag) + noise * rng.standard_normal(n)
    return {"lip": lip, "events": ev, "spikes": spikes, "pause": pause}


def test_fit_recovers_lag_and_target_order():
    rng = np.random.default_rng(0)
    clips = [make_clip(rng) for _ in range(40)]
    fit = co.fit_prior(clips, lags=range(-1, 4), passes=1, log=lambda s: None)
    assert fit["lag"] == 2 and fit["train_corr"] > 0.9
    tg = fit["targets"]
    assert tg["a"] > tg["i"] > tg["u"] > tg["f"] > tg["p"]                 # open > ... > closed


def test_prior_trace_is_a_weighted_average_of_targets():
    ev = [(5, "a", "open vowel"), (15, "p", "closure p/b/m")]
    tg = {"a": 1.0, "p": -1.0}
    al = {k: 1.0 for k in co.CLASSES}
    th = {k: 0.5 for k in co.CLASSES}
    p = co.prior_trace(ev, 21, tg, al, th)
    assert abs(p[10] - 0.0) < 1e-9 and p[5] > 0.9 and p[15] < -0.9      # midway: equal pull
    al["closure p/b/m"] = 4.0                                             # a dominant closure wins the middle
    assert co.prior_trace(ev, 21, tg, al, th)[10] < -0.5
    assert not co.prior_trace([], 10, tg, al, th).any()


def test_partial_corr_is_zero_when_the_prior_adds_nothing_and_large_when_it_does():
    rng = np.random.default_rng(1)
    real = np.convolve(rng.standard_normal(300), np.ones(5) / 5, "same")
    gen = real + 0.5 * rng.standard_normal(300)
    copy = 2 * gen + 1                                                    # the prior knows only what SANG knows
    assert abs(co.partial_corr(real, copy, gen)) < 1e-9 or np.isnan(co.partial_corr(real, copy, gen))
    other = real + 0.5 * rng.standard_normal(300)                         # independent information about real
    assert co.partial_corr(real, other, gen) > 0.3


def test_blend_gains_only_when_the_prior_has_new_information():
    rng = np.random.default_rng(2)
    clips_new, clips_none = [], []
    for _ in range(20):
        real = np.convolve(rng.standard_normal(200), np.ones(5) / 5, "same")
        gen = real + 0.4 * rng.standard_normal(200)
        clips_new.append({"lip": real, "gen": gen, "prior": real + 0.4 * rng.standard_normal(200)})
        clips_none.append({"lip": real, "gen": gen, "prior": gen + 0.01 * rng.standard_normal(200)})
    assert co.blend_gain(clips_new)["gain"] > 0.03
    assert abs(co.blend_gain(clips_none)["gain"]) < 0.01


def run_noise_case(noise, rng, k=4):
    """SANG samples = model mean m + noise. Returns the mean partials of a prior that knows only m, of a
    prior with extra information, and of the half-vs-half baseline."""
    smooth = lambda: np.convolve(rng.standard_normal(400), np.ones(7) / 7, "same")
    same, new, base = [], [], []
    for _ in range(60):
        m, extra = smooth(), smooth()
        real = m + 0.6 * extra + 0.3 * smooth()
        gs = [m + noise * smooth() for _ in range(k)]
        a, b, mean = np.mean(gs[: k // 2], 0), np.mean(gs[k // 2:], 0), np.mean(gs, 0)
        same.append(co.partial_corr(real, m + 0.05 * smooth(), mean))
        new.append(co.partial_corr(real, m + 0.6 * extra + 0.05 * smooth(), mean))
        base.append(co.partial_corr(real, b, a))
    return np.mean(same), np.mean(new), np.mean(base)


def test_noisy_samples_give_inconclusive_not_a_false_go():
    rng = np.random.default_rng(3)
    same, new, base = run_noise_case(0.8, rng)
    assert same > 0.1                                                     # the naive test would say GO
    assert co.verdict(same, base) == "INCONCLUSIVE"                       # the baseline catches it


def test_with_a_pinned_down_mean_the_verdict_separates_new_information():
    rng = np.random.default_rng(5)
    same, new, base = run_noise_case(0.02, rng)
    assert base < 0.05
    assert co.verdict(same, base) == "NO-GO" and co.verdict(new, base) == "GO"


def test_least_squares_targets_undo_the_double_blur():
    rng = np.random.default_rng(4)
    clips = [make_clip(rng, noise=0.05) for _ in range(30)]
    al = {k: 1.0 for k in co.CLASSES}
    th = {k: 0.5 for k in co.CLASSES}
    start = co.fit_targets(clips, lag=2)
    ls = co.fit_targets_ls(clips, start, al, th, 2, ridge=1e-3)
    assert co.mean_corr(clips, ls, al, th, 2) > co.mean_corr(clips, start, al, th, 2)
    assert ls["a"] - ls["p"] > start["a"] - start["p"]                    # frame means are blurred toward each other


def test_cluster_interval_is_wider_when_clips_of_a_video_agree():
    x = np.repeat([0.0, 0.2, 0.4, 0.6], 25)                               # 4 videos, identical clips within each
    vids = np.repeat(list("abcd"), 25)
    m, ci_video = co.cluster_ci(x, vids)
    _, ci_clip = co.cluster_ci(x, np.arange(100))
    assert abs(m - 0.3) < 1e-12 and ci_video > 4 * ci_clip
